def apply(replacement):
    from menu_textures import patch
    entries={e['name']:e for e in json.loads((WORK/'inventory.json').read_text(encoding='utf-8'))['fbd']}
    grouped={}
    for f,t,ls in labels():grouped.setdefault((f,t),[]).extend(ls)
    with ISO.open('rb') as src:
        for (f,t),ls in grouped.items():
            if f not in entries:continue
            data=replacement.get(f)
            if data is None:
                e=entries[f];src.seek(e['offset']);data=src.read(e['size'])
            replacement[f]=patch(data,ls,ROOT/'build'/('preview_'+f+'_'+t+'.png'),t)
    return len(grouped)

if __name__=='__main__':
    print('Patched atlases:',apply({}))
